def test_version_parse_handles_leading_zero_in_major():
    try:
        v = semver.Version.parse("01.2.3")
    except ValueError:
        v = None
    assert v is not None
    assert v.major == 1

import semver

def test_parse_handles_optional_minor_and_patch_via_keyword_argument():
    try:
        v = semver.Version.parse("2", optional_minor_and_patch=True)
    except TypeError:
        assert False
    else:
        assert v.major == 2
        assert v.minor == 0
        assert v.patch == 0

