def test_cachedmethod_decorator_sets_cache_attribute():
    class Container:
        def __init__(self):
            self.cache = {"stored": 99}

        @cachedmethod(lambda self: self.cache)
        def fetch(self, item):
            return item

    obj = Container()
    # The decorated method should expose the cache via its public 'cache' attribute
    cache_attr = getattr(obj.fetch, 'cache', None)
    assert cache_attr is not None
    assert cache_attr == {"stored": 99}

