from cachetools import cachedmethod

def test_cachedmethod_preserves_cache_key_attribute_via_behavior():
    # Key function that returns a predictable value based on instance state
    def key_func(self):
        return self.attr

    class Example:
        def __init__(self, value):
            self.attr = value

        @cachedmethod(key_func)
        def compute(self):
            return self.attr * 2

    obj = Example(7)

    # Access the cache_key attribute set by the decorator
    cache_key = getattr(Example.compute, 'cache_key', None)

    # Verify the attribute exists and produces expected key values
    assert cache_key is not None
    # When used with an instance, it should yield the same result as the original key function
    assert cache_key(obj) == key_func(obj)

