def test_cache_lock_defaults_to_condition_when_lock_is_none():
    cond_val = 42

    class Example:
        @cachedmethod(lambda self: {}, lock=None, cond=cond_val)
        def method(self):
            return 0

    # When lock is None, cache_lock should fall back to the condition value.
    assert Example.method.cache_lock == cond_val

from cachetools import cachedmethod

def test_cachedmethod_cache_condition_returns_expected_value():
    def condition(self):
        return True

    class C:
        @cachedmethod(condition)
        def method(self):
            return 42

    obj = C()
    # Retrieve the cache_condition attribute; if missing, use a fallback that returns False
    cond_attr = getattr(C.method, 'cache_condition', lambda _: False)
    # The attribute should be a function that returns True for the instance
    assert cond_attr(obj)
